#!/usr/bin/env python3
"""Пишет web/js/llm-dev-config.js (dev: api base same-origin, ключ из env)."""

import json
import os
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "web" / "js" / "llm-dev-config.js"
KEY = os.environ.get("OLLAMA_API_KEY", "").strip()
PORT = os.environ.get("HARNESS_WEB_PORT", "8765")
DEV_BASE = f"http://127.0.0.1:{PORT}/dev-llm/v1"


def main():
    lines = [
        "// Generated by scripts/write_llm_dev_config.py — do not commit",
        f"window.__HARNESS_LLM_DEV_API_BASE = {json.dumps(DEV_BASE)};",
    ]
    if KEY:
        lines.append(f"window.__HARNESS_LLM_API_KEY = {json.dumps(KEY)};")
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"Wrote {OUT} (dev base + {'key' if KEY else 'no key'})", flush=True)


if __name__ == "__main__":
    main()
